// Trades where parts are always quoted separately at the job: the listed price is the pro's work, a part needs a photo and the customer's OK, and ZappyOne takes nothing on parts. Platform-free (websites and apps).
const PARTS_DOMAINS = new Set(['electronics', 'vehicles']);
const PARTS_VERTICALS = new Set(['mobile', 'laptop', 'two_wheeler', 'four_wheeler']);

export function partsQuotedSeparately(vertical, verticals = []) {
  if (PARTS_VERTICALS.has(vertical)) return true;
  const row = verticals.find((v) => v.vertical === vertical);
  return !!row && PARTS_DOMAINS.has(row.domainCode);
}

export const PARTS_NOTE = {
  customer: 'Prices are for the work. If a part is needed, your pro shows you a photo and the part price first; nothing is fitted until you approve.',
  partner: 'Price your work only. Parts are different every time, so you add them on the quote at the job with a photo; the customer approves, and ZappyOne takes nothing on parts.',
};

// ZappyOne's privacy promise, the same words wherever it is shown (booking, the pro's job screen).
export const PRIVACY_PLEDGE = {
  customer: 'No cameras, no recording in your home. Pros photograph only the work, never people.',
  partner: "Never record video or audio in a customer's home. Photograph only the work, never people.",
};

const GRADE_WORD = { original: 'original', oem: 'OEM', compatible: 'compatible' };

// One fitted part in words, for the device's history: "2 x Battery, original, 90-day warranty".
export function partLine(p = {}) {
  const bits = [`${(p.quantity || 1) > 1 ? `${p.quantity} x ` : ''}${p.label || 'Part'}`];
  if (GRADE_WORD[p.grade]) bits.push(GRADE_WORD[p.grade]);
  if (p.warrantyDays > 0) bits.push(`${p.warrantyDays}-day warranty`);
  return bits.join(', ');
}
